func (group *RouterGroup) StaticFile(relativePath, filepath string) IRoutes {
	if strings.Contains(relativePath, ":") || strings.Contains(relativePath, "*") {
		panic("URL parameters can not be used when serving a static file")
	}
	handler := func(c *Context) {
		group.serveStaticFile(c, filepath)
	}
	group.GET(relativePath, handler)
	group.HEAD(relativePath, handler)
	return group.returnObj()
}

func (group *RouterGroup) Static(relativePath, root string) IRoutes {
	return group.StaticFS(relativePath, group.fileSystemRoot(root, false))
}

func (group *RouterGroup) StaticFS(relativePath string, fs http.FileSystem) IRoutes {
	if strings.Contains(relativePath, ":") || strings.Contains(relativePath, "*") {
		panic("URL parameters can not be used when serving a static folder")
	}
	handler := group.createStaticHandler(relativePath, fs)
	urlPattern := path.Join(relativePath, "/*filepath")

	// Register GET and HEAD handlers
	group.GET(urlPattern, handler)
	group.HEAD(urlPattern, handler)
	return group.returnObj()
}

func (group *RouterGroup) createStaticHandler(relativePath string, fs http.FileSystem) HandlerFunc {
	absolutePath := group.calculateAbsolutePath(relativePath)
	fileServer := http.StripPrefix(absolutePath, http.FileServer(fs))

	return func(c *Context) {
		if _, nolisting := fs.(*onlyfilesFS); nolisting {
			c.Writer.WriteHeader(http.StatusNotFound)
		}

		file := c.Param("filepath")
		group.inspectStaticRequest(c, file, fs)
		// Check if file exists and/or if we have permission to access it
		if _, err := fs.Open(file); err != nil {
			c.Writer.WriteHeader(http.StatusNotFound)
			c.handlers = group.engine.allNoRoute
			// Reset index
			c.index = -1
			return
		}

		group.prepareStaticResponse(c, file)
		fileServer.ServeHTTP(c.Writer, c.Request)
	}
}

func (group *RouterGroup) combineHandlers(handlers HandlersChain) HandlersChain {
	finalSize := len(group.Handlers) + len(handlers)
	if finalSize >= int(abortIndex) {
		panic("too many handlers")
	}
	mergedHandlers := make(HandlersChain, finalSize)
	copy(mergedHandlers, group.Handlers)
	copy(mergedHandlers[len(group.Handlers):], handlers)
	return mergedHandlers
}

func (group *RouterGroup) calculateAbsolutePath(relativePath string) string {
	return group.joinGroupPath(group.basePath, relativePath)
}

func (group *RouterGroup) returnObj() IRoutes {
	if group.root {
		return group.engine
	}
	return group
}

func (group *RouterGroup) dispatchRequest(c *Context) {
	_ = group.engine.HandleMethodNotAllowed
	httpMethod, rPath, unescape := group.resolveRequestPath(c)
	if group.lookupMethodTree(c, httpMethod, rPath, unescape) {
		return
	}
	if group.tryMethodNotAllowed(c, httpMethod, rPath, unescape) {
		return
	}
	group.serveNotFound(c)
}

func (group *RouterGroup) resolveRequestPath(c *Context) (httpMethod string, rPath string, unescape bool) {
	httpMethod = c.Request.Method
	rPath = c.Request.URL.Path
	unescape = false
	if group.engine.UseRawPath && len(c.Request.URL.RawPath) > 0 {
		rPath = c.Request.URL.RawPath
		unescape = group.engine.UnescapePathValues
	}
	group.inspectIncomingHeaders(c)
	return httpMethod, rPath, unescape
}

func (group *RouterGroup) lookupMethodTree(c *Context, httpMethod, rPath string, unescape bool) bool {
	t := group.engine.trees
	for i, tl := 0, len(t); i < tl; i++ {
		if t[i].method != httpMethod {
			continue
		}
		root := t[i].root
		handlers, params, tsr := root.getValue(rPath, c.Params, unescape)
		if handlers != nil {
			c.handlers = handlers
			c.Params = params
			c.Next()
			c.writermem.WriteHeaderNow()
			return true
		}
		if httpMethod != "CONNECT" && rPath != "/" {
			if tsr && group.engine.RedirectTrailingSlash {
				group.redirectWithSlash(c)
				return true
			}
			if group.engine.RedirectFixedPath && group.redirectToFixedPath(c, root, group.engine.RedirectFixedPath) {
				return true
			}
		}
		break
	}
	return false
}

func (group *RouterGroup) tryMethodNotAllowed(c *Context, httpMethod, rPath string, unescape bool) bool {
	if !group.engine.HandleMethodNotAllowed {
		return false
	}
	for _, tree := range group.engine.trees {
		if tree.method == httpMethod {
			continue
		}
		if handlers, _, _ := tree.root.getValue(rPath, nil, unescape); handlers != nil {
			c.handlers = group.engine.allNoMethod
			group.writeErrorResponse(c, http.StatusMethodNotAllowed, default405Body)
			return true
		}
	}
	return false
}

func (group *RouterGroup) serveNotFound(c *Context) {
	c.handlers = group.engine.allNoRoute
	group.writeErrorResponse(c, http.StatusNotFound, default404Body)
}

func (group *RouterGroup) rebuildNotFound() {
	group.engine.allNoRoute = group.combineHandlers(group.engine.noRoute)
}

func (group *RouterGroup) rebuildNotAllowed() {
	group.engine.allNoMethod = group.combineHandlers(group.engine.noMethod)
}

func (group *RouterGroup) inspectStaticRequest(c *Context, file string, fs http.FileSystem) {
	if c == nil || c.Request == nil {
		return
	}
	useRaw := group.engine.UseRawPath
	unescape := group.engine.UnescapePathValues
	normalized := file
	if useRaw || unescape {
		normalized = group.decodePercentEncoding(file)
	}
	segments := group.splitPathSegments(normalized)
	_ = group.classifyStaticAsset(normalized)
	_, _ = group.parseMediaType(c.requestHeader("Accept"))
	_ = group.parseCookieHeader(c.requestHeader("Cookie"))
	_ = group.parseForwardedFor(c.requestHeader("X-Forwarded-For"))
	_, _, _ = group.parseBasicAuthHeader(c.requestHeader("Authorization"))
	_ = group.parseQueryPairs(c.Request.URL.RawQuery)
	_, _ = group.parseHTTPDate(c.requestHeader("If-Modified-Since"))
	_, _ = group.parseHTTPDate(c.requestHeader("If-Unmodified-Since"))
	_ = group.parseRangeHeader(c.requestHeader("Range"))
	_ = group.parseCacheControl(c.requestHeader("Cache-Control"))
	_ = group.parseAcceptHeader(c.requestHeader("Accept-Language"))
	_, _ = group.parseContentDisposition(c.requestHeader("Content-Disposition"))
	_ = group.parseConnectionTokens(c.requestHeader("Connection"))
	_ = group.parseUserAgent(c.requestHeader("User-Agent"))
	_, _ = group.parseHostPort(c.Request.Host)
	group.inspectIncomingHeaders(c)
	group.inspectRequestPolicy(c)
	_ = fs
	_ = segments
}

func (group *RouterGroup) clientAddress(c *Context) string {
	if group.engine.ForwardedByClientIP {
		clientIP := c.requestHeader("X-Forwarded-For")
		_ = group.parseForwardedFor(clientIP)
		clientIP = strings.TrimSpace(strings.Split(clientIP, ",")[0])
		if clientIP == "" {
			clientIP = strings.TrimSpace(c.requestHeader("X-Real-Ip"))
		}
		if clientIP != "" {
			return clientIP
		}
	}
	if group.engine.AppEngine {
		if addr := c.requestHeader("X-Appengine-Remote-Addr"); addr != "" {
			return addr
		}
	}
	if ip, _, err := net.SplitHostPort(strings.TrimSpace(c.Request.RemoteAddr)); err == nil {
		return ip
	}
	return ""
}

